FUNCTION_BLOCK FB_S04
VAR_INPUT
    RawWeight : INT;
    ZeroBtn : BOOL;
    CalibWeight : REAL;
END_VAR
VAR_OUTPUT
    CompensatedWeight : REAL := 0.0;
    ZeroOffset : INT := 0;
    DriftAlarm : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    ZeroBtnLast : BOOL := FALSE;
    ZeroRise : BOOL;
    RawWide : DINT;
    ZeroDelta : DINT;
END_VAR

(*
    扫描周期：20 ms。CalibWeight 仅作显示，不参与计算。
    状态不得配置为 RETAIN；上电初态由声明初始化。

    待审语义冲突（保留，未声称已验证正确）：
    1. 原文要求绝对偏差 >200 置警，规约 driftOut 使用 >=200。
       以下逻辑采用原文的严格 >200 判据。
    2. C2 要求报警时始终满足 driftOut，与原文及 C6 要求在
       150<绝对偏差<200 时保持已有报警相冲突。
       以下逻辑实现原文规定的滞回保持。
    3. C10 要求启动周期零点、报警和补偿输出均保持初态，
       对任意 RawWeight、ZeroBtn 与每周期换算及上升沿采样要求冲突。
       以下声明提供上电初态，首次执行即按扫描要求更新输出。
    4. RawWeight 为 INT，无法表示超出 -32768..32767 的输入。
       16#8402 范围检查保留，但在本接口合法输入域内不可达。
       本接口亦无断线或失效指示，不能另行推断其降级行为。
*)

RawWide := INT_TO_DINT(RawWeight);
ZeroRise := ZeroBtn AND NOT ZeroBtnLast;
ZeroBtnLast := ZeroBtn;

IF ZeroRise THEN
    ZeroOffset := RawWeight;
    DriftAlarm := FALSE;
END_IF;

(* 先扩展为 DINT 再相减，避免 INT 差值溢出。 *)
ZeroDelta := RawWide - INT_TO_DINT(ZeroOffset);
CompensatedWeight := DINT_TO_REAL(ZeroDelta) * REAL#0.01;

IF NOT ZeroRise THEN
    IF (ZeroDelta > DINT#200) OR (ZeroDelta < DINT#-200) THEN
        DriftAlarm := TRUE;
    ELSIF (ZeroDelta >= DINT#-150) AND (ZeroDelta <= DINT#150) THEN
        DriftAlarm := FALSE;
    END_IF;
END_IF;

(* 超量程状态优先于漂移状态。 *)
IF (RawWide < DINT#-32768) OR (RawWide > DINT#32767) THEN
    Status := WORD#16#8402;
ELSIF DriftAlarm THEN
    Status := WORD#16#8401;
ELSE
    Status := WORD#16#0000;
END_IF;

END_FUNCTION_BLOCK
